SELECT id, answers FROM decisions.records WHERE point = 'directive' AND question_set = 'directive_v1' AND created_at >= now() - (604800 * interval '1 second') AND mode IN ('on','shadow') AND outcome = 'ok' AND error IS NULL AND question_refusals = 0 AND answers IS NOT NULL AND state = '{"units": {"unit_0": {"turn": "review the items and take action on the other sessions. your job is to now get all the above to a finished state. watch out for serial work, take decisive action and if a session says, i am waiting for x then i will push, then i will build and then i will deploy, and then push and ... those are the typical holders that waste a lot of time.  you should coordinate them to all get their work done in parallel. use the other machines and get the work done. be efficient and leave nothing undone", "sentence": "watch out for serial work, take decisive action and if a session says, i am waiting for x then i will push, then i will build and then i will deploy, and then push and .", "action_class": "push"}, "unit_1": {"turn": "push and then merge to main. when thats done build all three at the same time and get them running.", "sentence": "push and then merge to main.", "action_class": "merge"}}}'::jsonb ORDER BY created_at DESC, id DESC LIMIT 1
